using System.Collections.Generic;
using System.IO;
using System.Reflection;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using Autodesk.Revit.UI;

namespace BIMinFormation.Revit.UI
{
    /// <summary>
    /// Ribbon button icons, embedded in the DLL (generated by <c>tools/make-icons.ps1</c>): 32×32 on the button and 16×16
    /// on the quick access toolbar, at 96 dpi, in one color for the light theme and another for the dark one (Revit 2024+).
    /// </summary>
    internal static class RibbonIcons
    {
        private static readonly List<(PushButton Button, string Name)> Buttons = new List<(PushButton, string)>();

        public static void Set(PushButton button, string name)
        {
            Buttons.Add((button, name));
            Apply(button, name, Dark());
        }

        /// <summary>Changes the colors of every button (the user changed the Revit theme).</summary>
        public static void Refresh()
        {
            bool dark = Dark();
            foreach (var (button, name) in Buttons) Apply(button, name, dark);
        }

        private static bool Dark()
        {
#if REVIT2025_OR_GREATER
            return UIThemeManager.CurrentTheme == UITheme.Dark;
#else
            return false;
#endif
        }

        private static void Apply(PushButton button, string name, bool dark)
        {
            string theme = dark ? "dark" : "light";
            button.LargeImage = Load(name + "-32-" + theme);
            button.Image = Load(name + "-16-" + theme);
        }

        private static ImageSource? Load(string name)
        {
            using var stream = Assembly.GetExecutingAssembly().GetManifestResourceStream("BIMinFormation.Revit.Icons." + name + ".png");
            if (stream == null)
            {
                Log.Error("Icon not found in the DLL: " + name);
                return null;
            }

            var image = new BitmapImage();
            image.BeginInit();
            image.CacheOption = BitmapCacheOption.OnLoad; // reads everything now: the stream is closed right after
            image.StreamSource = stream;
            image.EndInit();
            image.Freeze();
            return image;
        }
    }
}
